cat > /workspace/tc.py <<'EOF'
import zipfile,sys,re
from lxml import etree
W="{http://schemas.openxmlformats.org/wordprocessingml/2006/main}"
z=zipfile.ZipFile(sys.argv[1]); root=etree.fromstring(z.read("word/document.xml"))
mode=sys.argv[2] if len(sys.argv)>2 else "changed"
def ptext(p):
    out=[];ch=False
    for el in p.iter():
        if el.tag==W+"t":
            anc=[a.tag for a in el.iterancestors()]
            if W+"ins" in anc: out.append("{+"+(el.text or "")+"+}");ch=True
            else: out.append(el.text or "")
        elif el.tag==W+"delText":
            out.append("[-"+(el.text or "")+"-]");ch=True
        elif el.tag==W+"tab": out.append("\t")
    s="".join(out).replace("+}{+","").replace("-][-","")
    return s,ch
i=0
for p in root.iter(W+"p"):
    i+=1
    s,ch=ptext(p)
    if mode=="all" or ch or re.search(r"(?i)comment|note to|rationale",s):
        if s.strip(): print(i,":",s)
EOF
