import openpyxl,sys
wb=openpyxl.load_workbook(sys.argv[1])
for ws in wb:
    print("=== SHEET",ws.title,ws.max_row,ws.max_column)
    rows=list(ws.iter_rows(values_only=True))
    # find header row: first row with >=3 non-null
    hi=0
    for i,r in enumerate(rows):
        if sum(v is not None for v in r)>=3: hi=i;break
    for r in rows[:hi]:
        if any(v is not None for v in r): print("PRE:",[v for v in r if v is not None])
    hdr=rows[hi]
    for r in rows[hi+1:]:
        if not any(v is not None for v in r): continue
        print("---")
        for h,v in zip(hdr,r):
            if v is not None and v!="": print(f"  {h}: {v}")
EOF
